import https from "node:https";
import os from "node:os";
const wildcardHosts = new Set([
	"0.0.0.0",
	"::",
	"0000:0000:0000:0000:0000:0000:0000:0000"
]);
export async function logListeningOn(logger, server, configuredHost) {
	// `standalone()` calls this after awaiting the logger, and for an IP literal host
	// `listening` may already have fired by then (#18381).
	if (!server.listening) {
		await new Promise((resolve) => server.once("listening", resolve));
	}
	const protocol = server instanceof https.Server ? "https" : "http";
	// Allow to provide host value at runtime
	const host = getResolvedHostForHttpServer(configuredHost);
	const { port } = server.address();
	const address = getNetworkAddress(protocol, host, port);
	if (host === undefined || wildcardHosts.has(host)) {
		logger.info(`Server listening on \n  local: ${address.local[0]} \t\n  network: ${address.network[0]}\n`);
	} else {
		logger.info(`Server listening on ${address.local[0]}`);
	}
}
function getResolvedHostForHttpServer(host) {
	if (host === false) {
		// Use a secure default
		return "localhost";
	} else if (host === true) {
		// If passed --host in the CLI without arguments
		return undefined;
	} else {
		return host;
	}
}
// this code from vite https://github.com/vitejs/vite/blob/d09bbd093a4b893e78f0bbff5b17c7cf7821f403/packages/vite/src/node/utils.ts#L892-L914
function getNetworkAddress(protocol = "http", hostname, port, base) {
	const NetworkAddress = {
		local: [],
		network: []
	};
	Object.values(os.networkInterfaces()).flatMap((nInterface) => nInterface ?? []).filter((detail) => detail && detail.address && detail.family === "IPv4").forEach((detail) => {
		let host = detail.address.replace("127.0.0.1", hostname === undefined || wildcardHosts.has(hostname) ? "localhost" : hostname);
		// ipv6 host
		if (host.includes(":")) {
			host = `[${host}]`;
		}
		const url = `${protocol}://${host}:${port}${base ? base : ""}`;
		if (detail.address.includes("127.0.0.1")) {
			NetworkAddress.local.push(url);
		} else {
			NetworkAddress.network.push(url);
		}
	});
	return NetworkAddress;
}
